import{_ as n,o as e,c as t,a2 as i}from"./chunks/framework.CqpfiAoK.js";const g=JSON.parse('{"title":"Indeks Ketentuan Hukum","description":"","frontmatter":{},"headers":[],"relativePath":"id/92-法律条文索引.md","filePath":"id/92-法律条文索引.md","lastUpdated":1789183869000}'),s={name:"id/92-法律条文索引.md"};function r(d,a,k,u,m,l){return e(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="indeks-ketentuan-hukum" tabindex="-1">Indeks Ketentuan Hukum <a class="header-anchor" href="#indeks-ketentuan-hukum" aria-label="Permalink to &quot;Indeks Ketentuan Hukum&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Isi</th></tr></thead><tbody><tr><td>Nomor Dokumen</td><td>92</td></tr><tr><td>Modul</td><td>Lampiran dan Bahan Rujukan</td></tr><tr><td>Kata Kunci Inti</td><td>indeks hukum, Konstitusi Simbiosis, hukum ketenagakerjaan, hukum perlindungan konsumen, hukum pendukung</td></tr></tbody></table><h2 id="_1-penjelasan-indeks" tabindex="-1">1. Penjelasan Indeks <a class="header-anchor" href="#_1-penjelasan-indeks" aria-label="Permalink to &quot;1. Penjelasan Indeks&quot;">​</a></h2><p>Indeks ini memuat dokumen hukum utama yang berlaku saat ini dan ketentuan intinya dari Peradaban Simbiosis Jangkar, disusun berdasarkan hierarki hukum dan departemen. Cakupan indeks mencakup &quot;Konstitusi Simbiosis&quot;, &quot;Hukum Ketenagakerjaan Simbiosis&quot;, &quot;Hukum Perlindungan Konsumen&quot;, serta lima hukum pendukung tentang pendidikan, kesehatan, perumahan, lingkungan, dan antimonopoli. Setiap entri indeks mencantumkan nama hukum, nomor ketentuan, dan ringkasan isi inti ketentuan tersebut. Indeks ini adalah alat referensi; untuk teks lengkap ketentuan hukum dan interpretasi yudisial, silakan lihat teks resmi setiap hukum.</p><h2 id="_2-konstitusi-simbiosis" tabindex="-1">2. Konstitusi Simbiosis <a class="header-anchor" href="#_2-konstitusi-simbiosis" aria-label="Permalink to &quot;2. Konstitusi Simbiosis&quot;">​</a></h2><p>&quot;Konstitusi Simbiosis&quot; adalah hukum dasar Peradaban Simbiosis Jangkar, dengan kekuatan hukum tertinggi, disahkan pada saat pembentukan formal peradaban simbiosis.</p><table tabindex="0"><thead><tr><th>Nomor Ketentuan</th><th>Isi Inti</th></tr></thead><tbody><tr><td>Pasal 1</td><td>Menetapkan Hengyuanzhou (Alam Semesta Asal Wanling Hengmao) sebagai domain tata kelola Peradaban Simbiosis Jangkar; tujuan dasar peradaban simbiosis adalah mencapai simbiosis semua ras dan peningkatan dimensi kosmik</td></tr><tr><td>Pasal 2</td><td>Menetapkan anti-penjarahan sebagai sikap dasar peradaban; melarang segala bentuk kultivasi gaya penjarahan dan penjarahan sumber daya</td></tr><tr><td>Pasal 3</td><td>Menetapkan &quot;mengembalikan hak memilih nasib dan evolusi kepada semua makhluk berkesadaran&quot; sebagai konsep inti peradaban</td></tr><tr><td>Pasal 4</td><td>Menetapkan lebih banyak kerja lebih banyak hasil, pertumbuhan mandiri, semua orang punya jalan, semua ras maju bersama sebagai kebijakan dasar peradaban</td></tr><tr><td>Pasal 5</td><td>Menetapkan sistem pembukaan gratis tiga ratus set sistem kultivasi asal; tidak ada organisasi atau individu yang boleh memonopoli otorisasi transmisi sistem kultivasi</td></tr><tr><td>Pasal 6</td><td>Menetapkan mekanisme kontrak produksi bersama sebagai sistem alokasi sumber daya dasar</td></tr><tr><td>Pasal 7</td><td>Menetapkan strategi aktivasi 20% sebagai tujuan nasional bertahap</td></tr><tr><td>Pasal 8</td><td>Menetapkan prinsip berbasis realitas; dunia nyata adalah satu-satunya dunia nyata, pengaturan fiktif tidak memiliki kekuatan hukum</td></tr><tr><td>Pasal 9</td><td>Menetapkan jalur peningkatan dimensi empat tahap sebagai strategi pengembangan jangka panjang peradaban</td></tr><tr><td>Pasal 10</td><td>Menetapkan prinsip kesetaraan semua ras; semua bentuk kehidupan setara di depan hukum</td></tr><tr><td>Pasal 11</td><td>Menetapkan prinsip evolusi simbiosis; evolusi individu tidak boleh dilakukan dengan mengorbankan hak evolusi individu atau kolektif lain</td></tr><tr><td>Pasal 12</td><td>Menetapkan prinsip lebih banyak kerja lebih banyak hasil; alokasi sumber daya mengambil kontribusi sebagai dasar inti</td></tr><tr><td>Pasal 13</td><td>Menetapkan prinsip pertumbuhan mandiri; menghormati hak setiap kehidupan untuk memilih evolusi secara mandiri</td></tr><tr><td>Pasal 14</td><td>Menetapkan prinsip semua orang punya jalan; negara berkewajiban memberikan setiap kehidupan jalur evolusi dasar dan jaminan sumber daya</td></tr><tr><td>Pasal 15</td><td>Menetapkan prinsip keberlanjutan; semua pembangunan harus mempertimbangkan keberlanjutan asal kosmik</td></tr><tr><td>Pasal 16-25</td><td>Menetapkan hak dasar semua makhluk berkesadaran: hak memilih evolusi, hak memperoleh sumber daya kultivasi, hak perlindungan setara, hak partisipasi simbiosis, hak pelestarian budaya, hak bantuan dan banding, hak kebebasan pribadi, hak martabat manusia, hak kebebasan berkeyakinan, hak kebebasan berekspresi</td></tr><tr><td>Pasal 26-31</td><td>Menetapkan kewajiban dasar semua makhluk berkesadaran: kewajiban mematuhi hukum, kewajiban menjaga ketertiban simbiosis, kewajiban kontribusi kerja, kewajiban melindungi lingkungan, kewajiban menghormati hak orang lain, kewajiban membimbing kultivator junior</td></tr><tr><td>Pasal 32</td><td>Menetapkan Dewan Jangkar sebagai otoritas tertinggi, terdiri dari perwakilan semua ras secara proporsional</td></tr><tr><td>Pasal 33</td><td>Menetapkan Komite Eksekutif Simbiosis sebagai lembaga administratif tertinggi</td></tr><tr><td>Pasal 34</td><td>Menetapkan Pengadilan Simbiosis sebagai lembaga yudisial tertinggi, menjalankan kekuasaan kehakiman secara mandiri</td></tr><tr><td>Pasal 35</td><td>Menetapkan Komite Pengawas Jangkar sebagai lembaga pengawas independen</td></tr><tr><td>Pasal 36</td><td>Menetapkan prosedur legislatif: rancangan hukum disahkan oleh mayoritas lebih dari setengah Dewan Jangkar</td></tr><tr><td>Pasal 37</td><td>Menetapkan prosedur amandemen konstitusi: harus disahkan oleh mayoritas lebih dari dua pertiga Dewan Jangkar dan disetujui oleh lebih dari setengah referendum nasional</td></tr><tr><td>Pasal 38</td><td>Menetapkan sistem peninjauan konstitusional; Pengadilan Simbiosis berhak menyatakan hukum yang melanggar Konstitusi tidak berlaku</td></tr><tr><td>Pasal 39</td><td>Menetapkan sistem litigasi konstitusional; semua makhluk berkesadaran dapat langsung mengajukan litigasi berdasarkan Konstitusi</td></tr><tr><td>Pasal 40</td><td>Menetapkan sistem otonomi lokal; setiap domain bintang dan setiap bidang menerapkan otonomi dalam kerangka konstitusional</td></tr><tr><td>Pasal 41</td><td>Menetapkan sistem republik semua ras; semua kelompok etnis setara dalam peradaban simbiosis dan menerapkan otonomi daerah</td></tr><tr><td>Pasal 42</td><td>Menetapkan sistem ekonomi peradaban simbiosis: berdasarkan kontrak produksi bersama, berbagai ekonomi kepemilikan berkembang bersama</td></tr><tr><td>Pasal 43</td><td>Menetapkan sistem kepemilikan negara dan distribusi adil sumber daya kultivasi</td></tr><tr><td>Pasal 44</td><td>Menetapkan sistem kesetaraan pendidikan, menjamin hak setiap kehidupan untuk pendidikan yang setara</td></tr><tr><td>Pasal 45</td><td>Menetapkan sistem jaminan kesehatan universal</td></tr><tr><td>Pasal 46</td><td>Menetapkan sistem jaminan perumahan, menjamin hak dasar setiap kehidupan untuk tempat tinggal</td></tr><tr><td>Pasal 47</td><td>Menetapkan prinsip dasar interaksi antar-bidang; tidak ada perjalanan antar-bidang yang tidak sah tanpa izin</td></tr><tr><td>Pasal 48</td><td>Menetapkan bahwa output sah dari kegiatan arkeologi terbatas pada pengetahuan abstrak dan informasi; pengembalian materi dan energi dilarang</td></tr><tr><td>Pasal 49</td><td>Menetapkan prinsip dasar retrospeksi waktu; harus mengikuti prinsip observasi terlebih dahulu, kemudian intervensi terbatas</td></tr><tr><td>Pasal 50</td><td>Menetapkan bahwa hak interpretasi Konstitusi milik Pengadilan Simbiosis, dan hak amandemen Konstitusi milik Dewan Jangkar</td></tr></tbody></table><h2 id="_3-hukum-ketenagakerjaan-simbiosis" tabindex="-1">3. Hukum Ketenagakerjaan Simbiosis <a class="header-anchor" href="#_3-hukum-ketenagakerjaan-simbiosis" aria-label="Permalink to &quot;3. Hukum Ketenagakerjaan Simbiosis&quot;">​</a></h2><p>&quot;Hukum Ketenagakerjaan Simbiosis&quot; adalah hukum dasar yang mengatur hubungan kerja dan melindungi hak serta kepentingan pekerja, dengan Pasal 42 Konstitusi Simbiosis sebagai dasar legislatif.</p><table tabindex="0"><thead><tr><th>Nomor Ketentuan</th><th>Isi Inti</th></tr></thead><tbody><tr><td>Pasal 1</td><td>Tujuan legislatif: mengatur hubungan kerja, melindungi hak dan kepentingan sah pekerja, dan membangun hubungan kerja yang harmonis dan simbiosis</td></tr><tr><td>Pasal 2</td><td>Ruang lingkup penerapan: semua hubungan kerja di dalam Hengyuanzhou, termasuk kerja materi, kerja kultivasi, dan kerja kreatif</td></tr><tr><td>Pasal 3</td><td>Menetapkan prinsip kesetaraan kesempatan kerja bagi pekerja; melarang diskriminasi kerja berdasarkan ras, jenis kelamin, tingkat kultivasi, atau asal-usul</td></tr><tr><td>Pasal 4</td><td>Menetapkan prinsip kebebasan memilih pekerjaan bagi pekerja; melarang kerja paksa dan perbudakan</td></tr><tr><td>Pasal 5</td><td>Menetapkan sistem kontrak kerja; saat membangun hubungan kerja, harus dibuat kontrak kerja tertulis</td></tr><tr><td>Pasal 6</td><td>Menetapkan klausul wajib kontrak kerja: jangka waktu kontrak, isi pekerjaan, upah kerja, jam kerja, perlindungan kerja, asuransi sosial</td></tr><tr><td>Pasal 7</td><td>Menetapkan sistem kerja delapan jam dan sistem jam kerja tidak lebih dari empat puluh empat jam per minggu</td></tr><tr><td>Pasal 8</td><td>Menetapkan batasan lembur: lembur harian tidak boleh melebihi satu jam, keadaan khusus tidak boleh melebihi tiga jam, lembur bulanan tidak boleh melebihi tiga puluh enam jam</td></tr><tr><td>Pasal 9</td><td>Menetapkan standar upah lembur: 1,5 kali upah untuk lembur hari kerja, 2 kali upah untuk lembur hari libur, 3 kali upah untuk lembur hari libur nasional</td></tr><tr><td>Pasal 10</td><td>Menetapkan sistem jaminan upah minimum; standar upah minimum ditetapkan oleh setiap domain bintang sesuai kondisi lokal</td></tr><tr><td>Pasal 11</td><td>Menetapkan sistem pembayaran upah: upah harus dibayarkan bulanan kepada pekerja itu sendiri dalam bentuk moneter, dan tidak boleh dipotong atau ditahan tanpa alasan</td></tr><tr><td>Pasal 12</td><td>Menetapkan prinsip distribusi lebih banyak kerja lebih banyak hasil; menerapkan sistem distribusi dengan distribusi berdasarkan kerja sebagai主体 dan berbagai metode distribusi berdampingan</td></tr><tr><td>Pasal 13</td><td>Menetapkan sistem keselamatan dan kesehatan kerja; pemberi kerja harus menyediakan kondisi keselamatan dan kesehatan kerja yang memenuhi standar bagi pekerja</td></tr><tr><td>Pasal 14</td><td>Menetapkan perlindungan kelompok khusus: perlindungan kerja khusus untuk pekerja di bawah umur, pekerja perempuan, pekerja penyandang disabilitas, dan pekerja kultivasi rendah</td></tr><tr><td>Pasal 15</td><td>Menetapkan sistem pelatihan kejuruan; pemberi kerja berkewajiban melakukan pelatihan keterampilan kejuruan bagi pekerja</td></tr><tr><td>Pasal 16</td><td>Menetapkan hak dan kepentingan kerja kultivator: kerja kultivasi juga dilindungi oleh hukum ini; kepemilikan hasil kultivasi disepakati oleh kontrak</td></tr><tr><td>Pasal 17</td><td>Menetapkan sistem asuransi sosial pekerja: asuransi pensiun, asuransi kesehatan, asuransi pengangguran, asuransi kecelakaan kerja, asuransi melahirkan</td></tr><tr><td>Pasal 18</td><td>Menetapkan sistem kesejahteraan pekerja: pemberi kerja harus memberikan tunjangan kesejahteraan yang diperlukan bagi pekerja</td></tr><tr><td>Pasal 19</td><td>Menetapkan sistem penyelesaian perselisihan kerja: mekanisme penyelesaian empat tingkat negosiasi, mediasi, arbitrase, dan litigasi</td></tr><tr><td>Pasal 20</td><td>Menetapkan sistem serikat pekerja; pekerja berhak mengorganisir dan bergabung dengan serikat pekerja sesuai hukum untuk melindungi hak dan kepentingan sah mereka</td></tr><tr><td>Pasal 21</td><td>Menetapkan sistem kontrak kolektif; serikat pekerja mewakili karyawan dalam membuat kontrak kolektif dengan pemberi kerja</td></tr><tr><td>Pasal 22</td><td>Menetapkan bahwa peraturan dan ketentuan pemberi kerja harus dibahas oleh kongres perwakilan karyawan atau semua karyawan</td></tr><tr><td>Pasal 23</td><td>Menetapkan syarat dan prosedur pemutusan kontrak kerja</td></tr><tr><td>Pasal 24</td><td>Menetapkan sistem kompensasi ekonomi; pemberi kerja harus membayar kompensasi ekonomi saat memutuskan kontrak kerja sesuai hukum</td></tr><tr><td>Pasal 25</td><td>Menetapkan sistem ganti rugi atas pemutusan kontrak kerja yang melanggar hukum</td></tr><tr><td>Pasal 26</td><td>Menetapkan sistem manajemen penyaluran tenaga kerja, mengatur penyaluran tenaga kerja</td></tr><tr><td>Pasal 27</td><td>Menetapkan aturan khusus untuk kerja paruh waktu</td></tr><tr><td>Pasal 28</td><td>Menetapkan sistem pengawasan dan inspeksi; departemen administratif ketenagakerjaan mengawasi dan memeriksa kepatuhan pemberi kerja terhadap hukum dan peraturan ketenagakerjaan sesuai hukum</td></tr><tr><td>Pasal 29</td><td>Menetapkan tanggung jawab hukum: pemberi kerja yang melanggar hukum ini akan memikul tanggung jawab administratif, perdata, dan pidana sesuai hukum</td></tr><tr><td>Pasal 30</td><td>Menetapkan tanggal berlaku dan hak interpretasi hukum ini</td></tr></tbody></table><h2 id="_4-hukum-perlindungan-konsumen" tabindex="-1">4. Hukum Perlindungan Konsumen <a class="header-anchor" href="#_4-hukum-perlindungan-konsumen" aria-label="Permalink to &quot;4. Hukum Perlindungan Konsumen&quot;">​</a></h2><p>&quot;Hukum Perlindungan Konsumen&quot; adalah hukum dasar yang melindungi hak dan kepentingan sah konsumen dan mengatur perilaku pelaku usaha.</p><table tabindex="0"><thead><tr><th>Nomor Ketentuan</th><th>Isi Inti</th></tr></thead><tbody><tr><td>Pasal 1</td><td>Tujuan legislatif: melindungi hak dan kepentingan sah konsumen, menjaga tatanan sosial dan ekonomi, serta mendorong perkembangan sehat ekonomi pasar simbiosis</td></tr><tr><td>Pasal 2</td><td>Ruang lingkup penerapan: perlindungan hak dan kepentingan konsumen di dalam Hengyuanzhou yang membeli, menggunakan barang, atau menerima jasa untuk kebutuhan konsumsi sehari-hari</td></tr><tr><td>Pasal 3</td><td>Menetapkan prinsip dasar transaksi antara pelaku usaha dan konsumen: sukarela, kesetaraan, keadilan, kejujuran, dan kepercayaan</td></tr><tr><td>Pasal 4</td><td>Menetapkan prinsip perlindungan negara terhadap hak dan kepentingan sah konsumen; negara mengambil langkah-langkah untuk memastikan konsumen menjalankan hak mereka sesuai hukum</td></tr><tr><td>Pasal 5</td><td>Menetapkan sembilan hak dasar konsumen: hak keamanan, hak informasi, hak pilihan mandiri, hak transaksi adil, hak ganti rugi, hak berserikat, hak memperoleh pengetahuan, hak dihormati, hak pengawasan</td></tr><tr><td>Pasal 6</td><td>Menetapkan hak keamanan konsumen: konsumen menikmati hak agar keamanan pribadi dan harta benda tidak dirugikan saat membeli, menggunakan barang, dan menerima jasa</td></tr><tr><td>Pasal 7</td><td>Menetapkan hak informasi konsumen: konsumen menikmati hak untuk mengetahui situasi sebenarnya dari barang yang mereka beli atau gunakan atau jasa yang mereka terima</td></tr><tr><td>Pasal 8</td><td>Menetapkan hak pilihan mandiri konsumen: konsumen menikmati hak untuk memilih barang atau jasa secara mandiri</td></tr><tr><td>Pasal 9</td><td>Menetapkan hak transaksi adil konsumen: konsumen menikmati hak transaksi adil dan berhak menolak perilaku transaksi paksa</td></tr><tr><td>Pasal 10</td><td>Menetapkan hak ganti rugi konsumen: konsumen yang menderita kerugian pribadi atau harta benda karena membeli, menggunakan barang, atau menerima jasa menikmati hak untuk memperoleh ganti rugi sesuai hukum</td></tr><tr><td>Pasal 11</td><td>Menetapkan kewajiban dasar pelaku usaha: memenuhi kewajiban hukum dan kontraktual, menerima pengawasan, menjamin keamanan, memberikan informasi yang benar, mengeluarkan bukti, menjamin kualitas, memenuhi tiga jaminan, tidak boleh melakukan transaksi tidak adil, tidak boleh melanggar kepribadian</td></tr><tr><td>Pasal 12</td><td>Menetapkan kewajiban jaminan keamanan pelaku usaha: pelaku usaha harus memastikan bahwa barang atau jasa yang mereka berikan memenuhi persyaratan perlindungan keamanan pribadi dan harta benda</td></tr><tr><td>Pasal 13</td><td>Menetapkan kewajiban pengungkapan informasi pelaku usaha: pelaku usaha harus memberikan konsumen informasi yang benar tentang barang atau jasa, dan tidak boleh membuat publisitas palsu atau menyesatkan</td></tr><tr><td>Pasal 14</td><td>Menetapkan norma khusus untuk produk dan jasa kultivasi: pelaku usaha metode kultivasi, instrumen kultivasi, dan produk energi harus memiliki kualifikasi khusus, dan produk harus lulus sertifikasi keamanan</td></tr><tr><td>Pasal 15</td><td>Menetapkan pengaturan klausul baku: pelaku usaha tidak boleh mengecualikan atau membatasi hak konsumen, mengurangi atau membebaskan tanggung jawab pelaku usaha melalui klausul baku</td></tr><tr><td>Pasal 16</td><td>Menetapkan sistem pengembalian tanpa alasan tujuh hari: konsumen yang membeli barang melalui metode jarak jauh seperti internet berhak mengembalikan barang dalam waktu tujuh hari sejak tanggal penerimaan barang</td></tr><tr><td>Pasal 17</td><td>Menetapkan sistem tiga jaminan: jika barang atau jasa yang diberikan pelaku usaha tidak memenuhi persyaratan kualitas, konsumen dapat meminta perbaikan, penggantian, atau pengembalian sesuai peraturan negara</td></tr><tr><td>Pasal 18</td><td>Menetapkan sistem ganti rugi hukuman: jika pelaku usaha memiliki perilaku penipuan dalam memberikan barang atau jasa, mereka harus meningkatkan ganti rugi atas kerugian yang diderita konsumen sesuai permintaan konsumen, dan jumlah ganti rugi yang ditingkatkan harus tiga kali harga barang yang dibeli konsumen atau biaya jasa yang diterima</td></tr><tr><td>Pasal 19</td><td>Menetapkan organisasi konsumen: asosiasi konsumen dan organisasi konsumen lainnya adalah organisasi sosial yang didirikan sesuai hukum yang melakukan pengawasan sosial terhadap barang dan jasa untuk melindungi hak dan kepentingan sah konsumen</td></tr><tr><td>Pasal 20</td><td>Menetapkan saluran penyelesaian perselisihan konsumen: negosiasi dan penyelesaian dengan pelaku usaha, meminta mediasi asosiasi konsumen, mengajukan banding ke departemen administratif terkait, mengajukan arbitrase, mengajukan gugatan ke pengadilan</td></tr><tr><td>Pasal 21</td><td>Menetapkan pembalikan beban pembuktian dalam perselisihan: untuk barang tahan lama atau jasa seperti dekorasi, jika konsumen menemukan cacat dalam waktu enam bulan sejak tanggal penerimaan, pelaku usaha memikul beban pembuktian</td></tr><tr><td>Pasal 22</td><td>Menetapkan tanggung jawab administratif dan pidana pelaku usaha</td></tr><tr><td>Pasal 23</td><td>Menetapkan tanggal berlaku dan hak interpretasi hukum ini</td></tr></tbody></table><h2 id="_5-lima-hukum-pendukung" tabindex="-1">5. Lima Hukum Pendukung <a class="header-anchor" href="#_5-lima-hukum-pendukung" aria-label="Permalink to &quot;5. Lima Hukum Pendukung&quot;">​</a></h2><h3 id="_5-1-hukum-jaminan-pendidikan" tabindex="-1">5.1 Hukum Jaminan Pendidikan <a class="header-anchor" href="#_5-1-hukum-jaminan-pendidikan" aria-label="Permalink to &quot;5.1 Hukum Jaminan Pendidikan&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nomor Ketentuan</th><th>Isi Inti</th></tr></thead><tbody><tr><td>Pasal 1</td><td>Tujuan legislatif: menjamin hak pendidikan yang setara bagi semua makhluk berkesadaran, membangun sistem pendidikan simbiosis, dan mendorong perkembangan bersama budaya semua ras</td></tr><tr><td>Pasal 2-5</td><td>Menetapkan prinsip kesetaraan pendidikan, prinsip pendidikan gratis (tahap pendidikan dasar), prinsip keragaman pendidikan, prinsip inovasi pendidikan</td></tr><tr><td>Pasal 6-10</td><td>Menetapkan arsitektur sistem pendidikan prasekolah, pendidikan wajib, pendidikan menengah atas, pendidikan tinggi, pendidikan kultivasi</td></tr><tr><td>Pasal 11-15</td><td>Menetapkan sistem khusus untuk pendidikan kultivasi: norma pengajaran tiga ratus set sistem, sistem mentor, sistem alokasi sumber daya kultivasi</td></tr><tr><td>Pasal 16-20</td><td>Menetapkan hak dan kewajiban guru, sistem kualifikasi guru, jaminan perlakuan guru</td></tr><tr><td>Pasal 21-25</td><td>Menetapkan jaminan investasi pendidikan, pembangunan fasilitas pendidikan, informatisasi pendidikan, pendidikan khusus, pendidikan antar-ras</td></tr><tr><td>Pasal 26-30</td><td>Menetapkan sistem evaluasi pendidikan, sistem pengawasan pendidikan, tanggung jawab hukum dan ketentuan tambahan</td></tr></tbody></table><h3 id="_5-2-hukum-jaminan-kesehatan" tabindex="-1">5.2 Hukum Jaminan Kesehatan <a class="header-anchor" href="#_5-2-hukum-jaminan-kesehatan" aria-label="Permalink to &quot;5.2 Hukum Jaminan Kesehatan&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nomor Ketentuan</th><th>Isi Inti</th></tr></thead><tbody><tr><td>Pasal 1</td><td>Tujuan legislatif: membangun sistem jaminan kesehatan universal, menjamin hak kesehatan semua makhluk berkesadaran, dan meningkatkan tingkat kesehatan keseluruhan semua ras</td></tr><tr><td>Pasal 2-5</td><td>Menetapkan prinsip asuransi kesehatan universal, prinsip kesehatan dasar gratis, prinsip integrasi pengobatan Tionghoa dan Barat, prinsip inklusi pengobatan kultivasi</td></tr><tr><td>Pasal 6-10</td><td>Menetapkan sistem asuransi kesehatan multi-tingkat dari asuransi kesehatan dasar, asuransi penyakit serius, bantuan medis, asuransi kesehatan komersial</td></tr><tr><td>Pasal 11-15</td><td>Menetapkan manajemen institusi medis, sistem tenaga medis, kualitas dan keamanan medis, norma khusus untuk pengobatan kultivasi</td></tr><tr><td>Pasal 16-20</td><td>Menetapkan manajemen obat-obatan, manajemen peralatan medis, manajemen produk medis energi, sistem obat-obatan esensial</td></tr><tr><td>Pasal 21-25</td><td>Menetapkan sistem kesehatan masyarakat, pencegahan dan pengendalian penyakit, pendidikan kesehatan, pengobatan antar-ras, jaminan kesehatan kelompok khusus</td></tr><tr><td>Pasal 26-30</td><td>Menetapkan penyelesaian perselisihan medis, pengawasan medis, tanggung jawab hukum dan ketentuan tambahan</td></tr></tbody></table><h3 id="_5-3-hukum-jaminan-perumahan" tabindex="-1">5.3 Hukum Jaminan Perumahan <a class="header-anchor" href="#_5-3-hukum-jaminan-perumahan" aria-label="Permalink to &quot;5.3 Hukum Jaminan Perumahan&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nomor Ketentuan</th><th>Isi Inti</th></tr></thead><tbody><tr><td>Pasal 1</td><td>Tujuan legislatif: menjamin hak dasar tempat tinggal semua makhluk berkesadaran, membangun sistem jaminan perumahan multi-tingkat, dan mencapai tempat tinggal untuk semua</td></tr><tr><td>Pasal 2-5</td><td>Menetapkan prinsip jaminan hak tempat tinggal, prinsip kesetaraan perumahan, prinsip sewa dan beli bersamaan, prinsip perumahan berkelanjutan</td></tr><tr><td>Pasal 6-10</td><td>Menetapkan sistem penyediaan perumahan dari perumahan sewa publik, perumahan sewa terjangkau, perumahan hak milik bersama, perumahan komersial</td></tr><tr><td>Pasal 11-15</td><td>Menetapkan sistem dana provident perumahan, sistem subsidi perumahan, kebijakan dukungan rumah pertama, kebijakan perumahan khusus untuk kultivator</td></tr><tr><td>Pasal 16-20</td><td>Menetapkan standar konstruksi perumahan, penerapan teknologi ruang dalam perumahan, bangunan hijau, perumahan ramah lansia dan tanpa hambatan</td></tr><tr><td>Pasal 21-25</td><td>Menetapkan regulasi pasar real estat, regulasi pasar sewa perumahan, manajemen layanan properti, jaminan pemeliharaan perumahan</td></tr><tr><td>Pasal 26-30</td><td>Menetapkan pengawasan jaminan perumahan, tanggung jawab hukum dan ketentuan tambahan</td></tr></tbody></table><h3 id="_5-4-hukum-perlindungan-lingkungan" tabindex="-1">5.4 Hukum Perlindungan Lingkungan <a class="header-anchor" href="#_5-4-hukum-perlindungan-lingkungan" aria-label="Permalink to &quot;5.4 Hukum Perlindungan Lingkungan&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nomor Ketentuan</th><th>Isi Inti</th></tr></thead><tbody><tr><td>Pasal 1</td><td>Tujuan legislatif: melindungi dan memperbaiki lingkungan, mencegah dan mengendalikan polusi dan bahaya publik lainnya, menjamin kesehatan masyarakat, mendorong pembangunan peradaban ekologis kosmik, dan mendorong pembangunan berkelanjutan</td></tr><tr><td>Pasal 2-5</td><td>Menetapkan prinsip prioritas perlindungan, prinsip pencegahan utama, prinsip pengelolaan komprehensif, prinsip partisipasi publik, prinsip tanggung jawab atas kerusakan</td></tr><tr><td>Pasal 6-10</td><td>Menetapkan sistem pengawasan dan pengelolaan lingkungan, sistem standar lingkungan, sistem penilaian dampak lingkungan, sistem pemantauan lingkungan, pengelolaan lingkungan antar-bidang</td></tr><tr><td>Pasal 11-15</td><td>Menetapkan pencegahan dan pengendalian polusi udara, pencegahan dan pengendalian polusi air, pencegahan dan pengendalian polusi tanah, pencegahan dan pengendalian polusi energi, pencegahan dan pengendalian polusi hukum</td></tr><tr><td>Pasal 16-20</td><td>Menetapkan pengolahan limbah padat, pencegahan dan pengendalian polusi suara, pencegahan dan pengendalian polusi radioaktif, perlindungan ekologis, perlindungan keanekaragaman hayati</td></tr><tr><td>Pasal 21-25</td><td>Menetapkan pengendalian dampak lingkungan dari kegiatan kultivasi, perlindungan ekologis dari pertambangan energi, persyaratan lingkungan untuk arkeologi antar-bidang</td></tr><tr><td>Pasal 26-30</td><td>Menetapkan pengungkapan informasi dan partisipasi publik, litigasi kepentingan publik lingkungan, tanggung jawab hukum dan ketentuan tambahan</td></tr></tbody></table><h3 id="_5-5-hukum-antimonopoli" tabindex="-1">5.5 Hukum Antimonopoli <a class="header-anchor" href="#_5-5-hukum-antimonopoli" aria-label="Permalink to &quot;5.5 Hukum Antimonopoli&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nomor Ketentuan</th><th>Isi Inti</th></tr></thead><tbody><tr><td>Pasal 1</td><td>Tujuan legislatif: mencegah dan menghentikan perilaku monopoli, melindungi persaingan adil pasar, meningkatkan efisiensi operasi ekonomi, menjaga kepentingan konsumen dan kepentingan publik sosial, serta mendorong perkembangan sehat ekonomi pasar simbiosis</td></tr><tr><td>Pasal 2-5</td><td>Menetapkan posisi dasar kebijakan persaingan, sistem peninjauan persaingan adil, larangan perjanjian monopoli, larangan penyalahgunaan posisi dominan pasar, pengendalian konsentrasi pelaku usaha</td></tr><tr><td>Pasal 6-10</td><td>Menetapkan identifikasi dan pengecualian perjanjian monopoli, perjanjian monopoli horizontal, perjanjian monopoli vertikal, perilaku monopoli asosiasi industri</td></tr><tr><td>Pasal 11-15</td><td>Menetapkan identifikasi posisi dominan pasar, jenis perilaku penyalahgunaan posisi dominan pasar, larangan penetapan harga predator</td></tr><tr><td>Pasal 16-20</td><td>Menetapkan standar deklarasi konsentrasi pelaku usaha, prosedur peninjauan, syarat restriktif tambahan, keputusan larangan konsentrasi</td></tr><tr><td>Pasal 21-25</td><td>Menetapkan larangan khusus monopoli sistem kultivasi: larangan memonopoli metode kultivasi, larangan monopoli sumber daya kultivasi, larangan monopoli jaringan mentor</td></tr><tr><td>Pasal 26-30</td><td>Menetapkan lembaga penegak hukum antimonopoli, prosedur investigasi, tanggung jawab hukum, sistem pengampunan dan ketentuan tambahan</td></tr></tbody></table><h2 id="penutup" tabindex="-1">Penutup <a class="header-anchor" href="#penutup" aria-label="Permalink to &quot;Penutup&quot;">​</a></h2><p>Indeks ketentuan hukum adalah peta referensi dari sistem pemerintahan berdasarkan hukum Peradaban Simbiosis Jangkar. Dari Konstitusi Simbiosis sebagai hukum dasar, hingga Hukum Ketenagakerjaan dan Hukum Perlindungan Konsumen yang mengatur kehidupan rakyat, kemudian lima hukum pendukung, mereka bersama-sama membentuk sistem hukum yang lengkap &quot;dengan Konstitusi sebagai komandan, hukum dasar sebagai tulang punggung, dan hukum pendukung sebagai penyangga&quot;. Sistem ini memastikan bahwa semua kegiatan peradaban simbiosis beroperasi di jalur pemerintahan berdasarkan hukum, memberikan jaminan institusional yang solid untuk kemajuan bersama semua ras.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen Terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen Terkait&quot;">​</a></h2><ul><li>40-Garis Besar Konstitusi Simbiosis</li><li>41-Hukum Ketenagakerjaan Simbiosis</li><li>48-Sistem Yudisial dan Mekanisme Putusan</li></ul>',28)])])}const h=n(s,[["render",r]]);export{g as __pageData,h as default};
